CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, email TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', picture TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT 'guest', locale TEXT NOT NULL DEFAULT 'id', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email_lower ON users(lower(email));
CREATE TABLE IF NOT EXISTS accurate_session (id BIGINT PRIMARY KEY CHECK (id = 1), provider TEXT NOT NULL DEFAULT 'web', email TEXT NOT NULL DEFAULT '', device_id TEXT NOT NULL DEFAULT '', cookies TEXT NOT NULL DEFAULT '[]', tenant TEXT NOT NULL DEFAULT '', official_session TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS accurate_accounts (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, provider TEXT NOT NULL DEFAULT 'web', enabled INTEGER NOT NULL DEFAULT 1, email TEXT NOT NULL DEFAULT '', password_encrypted TEXT NOT NULL DEFAULT '', api_token_encrypted TEXT NOT NULL DEFAULT '', signature_secret_encrypted TEXT NOT NULL DEFAULT '', device_id TEXT NOT NULL DEFAULT '', cookies TEXT NOT NULL DEFAULT '[]', tenant TEXT NOT NULL DEFAULT '', official_session TEXT NOT NULL DEFAULT '', is_default INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_accurate_accounts_name_lower ON accurate_accounts(lower(name));
CREATE UNIQUE INDEX IF NOT EXISTS idx_accurate_accounts_default ON accurate_accounts(is_default) WHERE is_default = 1;
CREATE TABLE IF NOT EXISTS page_designs (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,paper TEXT NOT NULL DEFAULT 'A4',paper_width_mm DOUBLE PRECISION NOT NULL DEFAULT 210,paper_height_mm DOUBLE PRECISION NOT NULL DEFAULT 297,label_width_mm DOUBLE PRECISION NOT NULL,label_height_mm DOUBLE PRECISION NOT NULL,cols INTEGER NOT NULL DEFAULT 1,rows INTEGER NOT NULL DEFAULT 1,gap_x_mm DOUBLE PRECISION NOT NULL DEFAULT 0,gap_y_mm DOUBLE PRECISION NOT NULL DEFAULT 0,margin_top_mm DOUBLE PRECISION NOT NULL DEFAULT 0,margin_left_mm DOUBLE PRECISION NOT NULL DEFAULT 0,is_audit_sheet INTEGER NOT NULL DEFAULT 0,label_layout TEXT DEFAULT NULL,settings_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS label_layout_presets (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,label_layout TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_label_layout_presets_name_lower ON label_layout_presets(lower(name));
CREATE TABLE IF NOT EXISTS roles (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',is_system INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_roles_name_lower ON roles(lower(name));
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,permission TEXT NOT NULL,PRIMARY KEY(role_id,permission));
CREATE TABLE IF NOT EXISTS migration_markers (name TEXT PRIMARY KEY,applied_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
